    private static final List<String> TILE_LIST = new ArrayList<>();
    private static final List<int[]> BLOCK_LIST = new ArrayList<>();
    private static final Map<String, Integer> ID = new HashMap<>();
    private static final Map<Material, Integer> CACHE = new ConcurrentHashMap<>();
    private static String json;

    static {
        TILE_LIST.add("");   // Kachel 0 = weiss
        for (String part : TILES) {
            for (String s : part.split("\\|")) if (!s.isEmpty()) TILE_LIST.add(s);
        }
        for (String part : BLOCKS) {
            for (String e : part.split(";")) {
                if (e.isEmpty()) continue;
                int eq = e.indexOf('='), cm = e.indexOf(',');
                BLOCK_LIST.add(new int[]{Integer.parseInt(e.substring(eq + 1, cm)), Integer.parseInt(e.substring(cm + 1))});
                ID.put(e.substring(0, eq), BLOCK_LIST.size());   // ids ab 1, 0 = unbekannt
            }
        }
    }

    private BlockTex() {}

    /** Block-ID (ab 1) oder 0, wenn unbekannt. */
    static int id(Material m) {
        Integer v = CACHE.get(m);
        if (v == null) {
            int id = 0;
            try {
                id = ID.getOrDefault(m.getKey().getKey(), 0);
            } catch (Exception ignored) {
            }
            v = id;
            CACHE.put(m, v);
        }
        return v;
    }

    /** {"tiles":[...],"top":[...],"side":[...]}, Index = Kachel- bzw. Block-ID. */
    static synchronized String json() {
        if (json == null) {
            StringBuilder sb = new StringBuilder(80000);
            sb.append("{\"tiles\":[");
            for (int i = 0; i < TILE_LIST.size(); i++) {
                if (i > 0) sb.append(',');
                sb.append('"').append(TILE_LIST.get(i)).append('"');
            }
            sb.append("],\"top\":[0");
            for (int[] b : BLOCK_LIST) sb.append(',').append(b[0]);
            sb.append("],\"side\":[0");
            for (int[] b : BLOCK_LIST) sb.append(',').append(b[1]);
            json = sb.append("]}").toString();
        }
        return json;
    }

    /** Alle Textur-Dateinamen (ohne .png), die in den Kacheln vorkommen. */
    static Set<String> textureNames() {
        Set<String> out = new LinkedHashSet<>();
        for (String spec : TILE_LIST) {
            if (spec.isEmpty() || spec.charAt(0) == '#') continue;
            String main = spec.split("@")[0];
            for (String n : main.split("\\+")) out.add(n);
        }
        return out;
    }
